// Portfolio Le Huu Chau - Base Script
console.log('Portfolio Le Huu Chau initialized.');
window.BG_DATA="data:image/jpeg;base64,";
window.ART_DATA={"s": "data:image/jpeg;base64,", "f": "data:image/jpeg;base64,", "c": "data:image/jpeg;base64,", "b": "data:image/jpeg;base64,"};

;

function $(selector, root) {
  return (root || document).querySelector(selector);
}

function $$(selector, root) {
  return Array.prototype.slice.call((root || document).querySelectorAll(selector));
}

var finePointer = matchMedia('(hover: hover) and (pointer: fine)').matches;

/* ===== Bật / tắt hiệu ứng =====
   Lưu lựa chọn của người xem; nếu chưa chọn thì tự tắt trên máy rất yếu. */
var FX_KEY = 'portfolio-fx';

function readSavedFx() {
  try { return localStorage.getItem(FX_KEY); } catch (e) { return null; }
}

function isWeakDevice() {
  var cores = navigator.hardwareConcurrency || 8;
  var memory = navigator.deviceMemory || 8;
  return cores <= 2 || memory <= 2;
}

var savedFx = readSavedFx();
var fxOn = savedFx ? savedFx === 'on' : !isWeakDevice();
var reduced = !fxOn;
document.documentElement.classList.toggle('fx-off', !fxOn);

function setFx(on, save) {
  fxOn = !!on;
  reduced = !fxOn;
  document.documentElement.classList.toggle('fx-off', !fxOn);
  if (save) {
    try { localStorage.setItem(FX_KEY, fxOn ? 'on' : 'off'); } catch (e) {}
  }
  window.dispatchEvent(new Event('fxchange'));
}

;

/* ===== js/loader.js ===== */
(function () {
  var loader = $('#loader');
  var bar = $('.ld-bar i');
  var startTime = performance.now();
  var duration = reduced ? 0 : 1200;
  var finished = false;

  function finish() {
    if (finished) return;
    finished = true;
    loader.classList.add('done');
    document.body.classList.add('ready');
    setTimeout(function () { loader.remove(); }, 900);
  }

  function tick(now) {
    var elapsed = (now || performance.now()) - startTime;
    var progress = duration ? Math.min(1, elapsed / duration) : 1;
    bar.style.width = (progress * 100) + '%';

    var pageLoaded = document.readyState === 'complete';
    if (progress >= 1 && (pageLoaded || elapsed > 3500)) {
      finish();
    } else {
      requestAnimationFrame(tick);
    }
  }

  tick(startTime);
  setTimeout(finish, 5000);
})();

;

/* ===== js/background.js ===== */
(function () {
  var canvas = $('#gl');
  var image = $('#bgsrc');
  var gl = canvas.getContext('webgl', { antialias: false, alpha: true }) ||
           canvas.getContext('experimental-webgl');

  image.src = window.BG_DATA;
  $('.bg-img').style.backgroundImage = 'url(' + image.src + ')';

  var failed = false, started = false, imageReady = false;
  var loop = null, loopId = null, lastFrame = 0;

  function pixelRatio() {
    return Math.min(devicePixelRatio || 1, finePointer ? 1.5 : 1);
  }

  function useFallback(reason) {
    if (reason) console.warn('Nền WebGL tắt, dùng ảnh tĩnh:', reason);
    failed = true;
    canvas.style.display = 'none';
  }

  if (!gl) { useFallback('không tạo được WebGL'); return; }

  var VERTEX_SHADER = 'attribute vec2 p;void main(){gl_Position=vec4(p,0.,1.);}';

  var FRAGMENT_SHADER = [
    '#ifdef GL_FRAGMENT_PRECISION_HIGH', 'precision highp float;', '#else', 'precision mediump float;', '#endif',
    'uniform sampler2D uTex,uFlow,uAct;uniform vec2 uRes,uImg,uMouse;uniform float uT,uVel;',
    'const float A=1.136;',
    'vec2 rot(vec2 d,float a){float c=cos(a),s=sin(a);return vec2(c*d.x-s*d.y,s*d.x+c*d.y);}',
    'vec2 swirl(vec2 uv,vec2 c,float r,float s,float ph){',
    ' vec2 d=uv-c;d.x*=A;float w=exp(-dot(d,d)/(r*r));',
    ' float a=s*w*(0.6+0.9*sin(uT*0.3+ph));d=rot(d,a);d.x/=A;return c+d-uv;}',
    'float glow(vec2 uv,vec2 c,float r,float ph){vec2 d=uv-c;d.x*=A;',
    ' return exp(-dot(d,d)/(r*r))*(0.5+0.5*sin(uT*0.9+ph));}',
    'void main(){',
    ' vec2 f=vec2(gl_FragCoord.x,uRes.y-gl_FragCoord.y);',
    ' float act=smoothstep(0.0,0.85,texture2D(uAct,vec2(gl_FragCoord.x/uRes.x,1.0-gl_FragCoord.y/uRes.y)).r);',
    ' vec2 d=f-uMouse;float R=0.16*max(uRes.x,uRes.y);',
    ' float w=exp(-dot(d,d)/(R*R));',
    ' f=uMouse+rot(d,w*uVel*(0.2+0.16*sin(uT*0.6)));',
    ' vec2 ax=uRes/uImg;float cv=max(ax.x,ax.y);',
    ' vec2 sc=mix(vec2(cv),ax,0.75);',
    ' sc.x=max(sc.x,sc.y/1.35);sc.y=max(sc.y,sc.x/1.35);sc=max(sc,ax)*1.03;',
    ' vec2 uv=(f-0.5*uRes)/(uImg*sc)+0.5;',
    ' float m=1.0-smoothstep(0.70,0.88,uv.y);',
    ' vec2 q=uv;',
    ' q+=m*act*(swirl(uv,vec2(0.55,0.33),0.30,0.30,0.0)+swirl(uv,vec2(0.60,0.52),0.12,0.55,0.7)+swirl(uv,vec2(0.08,0.21),0.10,0.7,2.0)',
    '   +swirl(uv,vec2(0.83,0.48),0.12,0.55,1.3)+swirl(uv,vec2(0.355,0.595),0.08,0.6,3.0)+swirl(uv,vec2(0.68,0.60),0.07,0.6,4.0)',
    '   +swirl(uv,vec2(0.63,0.667),0.08,0.6,5.0));',
    ' q+=m*act*0.005*vec2(sin(uv.y*14.0+uT*0.3+sin(uv.x*6.0)),cos(uv.x*12.0-uT*0.25));',
    ' vec2 e=texture2D(uFlow,uv).rg*2.0-1.0;',
    ' float coh=length(e);vec2 dir=vec2(cos(atan(e.y,e.x+1e-4)*0.5),sin(atan(e.y,e.x+1e-4)*0.5));',
    ' float amp=0.012*act*(0.35+0.65*m)*smoothstep(0.04,0.3,coh);',
    ' float p0=fract(uT*0.16),p1=fract(uT*0.16+0.5);',
    ' float w0=1.0-abs(2.0*p0-1.0);',
    ' vec3 c0=texture2D(uTex,q-dir*p0*amp).rgb;vec3 c1=texture2D(uTex,q-dir*p1*amp).rgb;',
    ' vec3 c=mix(c1,c0,w0);',
    ' float g=glow(q,vec2(0.60,0.52),0.05,0.0)+glow(q,vec2(0.08,0.21),0.04,1.5)+glow(q,vec2(0.83,0.48),0.045,3.0)',
    '  +glow(q,vec2(0.355,0.595),0.035,4.5)+glow(q,vec2(0.68,0.60),0.03,2.2)+glow(q,vec2(0.63,0.667),0.035,5.2);',
    ' c+=vec3(1.0,0.78,0.25)*g*0.28*act;',
    ' gl_FragColor=vec4(c*0.92,1.0);}'
  ].join('\n');

  function compileShader(type, source) {
    var shader = gl.createShader(type);
    gl.shaderSource(shader, source);
    gl.compileShader(shader);
    if (gl.getShaderParameter(shader, gl.COMPILE_STATUS)) return shader;
    console.warn('Lỗi shader:', gl.getShaderInfoLog(shader));
    return null;
  }

  var vertexShader = compileShader(gl.VERTEX_SHADER, VERTEX_SHADER);
  var fragmentShader = compileShader(gl.FRAGMENT_SHADER, FRAGMENT_SHADER);
  if (!vertexShader || !fragmentShader) { useFallback(); return; }

  var program = gl.createProgram();
  gl.attachShader(program, vertexShader);
  gl.attachShader(program, fragmentShader);
  gl.linkProgram(program);
  if (!gl.getProgramParameter(program, gl.LINK_STATUS)) {
    useFallback(gl.getProgramInfoLog(program));
    return;
  }
  gl.useProgram(program);

  var quad = gl.createBuffer();
  gl.bindBuffer(gl.ARRAY_BUFFER, quad);
  gl.bufferData(gl.ARRAY_BUFFER, new Float32Array([-1, -1, 1, -1, -1, 1, 1, 1]), gl.STATIC_DRAW);
  var positionLocation = gl.getAttribLocation(program, 'p');
  gl.enableVertexAttribArray(positionLocation);
  gl.vertexAttribPointer(positionLocation, 2, gl.FLOAT, false, 0, 0);

  var uniform = {};
  ['uTex', 'uFlow', 'uAct', 'uRes', 'uImg', 'uMouse', 'uT', 'uVel'].forEach(function (name) {
    uniform[name] = gl.getUniformLocation(program, name);
  });

  var GRID_W = 160, gridH = 90;
  var activity = new Float32Array(GRID_W * gridH);
  var activitySmooth = new Float32Array(GRID_W * gridH);
  var activityBytes = new Uint8Array(GRID_W * gridH);
  var hasActivity = false;
  var needsRedraw = true;

  var width, height;
  var mouseX = -9999, mouseY = -9999;
  var smoothX = -9999, smoothY = -9999;
  var velocity = 0;
  var pointerInside = false;
  var presence = 0;
  var lastX = null, lastY = null;
  var startTime = performance.now();

  function resize() {
    var ratio = pixelRatio();
    width = canvas.width = Math.round(innerWidth * ratio);
    height = canvas.height = Math.round(innerHeight * ratio);
    gl.viewport(0, 0, width, height);

    gridH = Math.max(8, Math.round(GRID_W * innerHeight / innerWidth));
    activity = new Float32Array(GRID_W * gridH);
    activitySmooth = new Float32Array(GRID_W * gridH);
    activityBytes = new Uint8Array(GRID_W * gridH);
    hasActivity = false;
    needsRedraw = true;
  }
  resize();
  addEventListener('resize', resize);

  function splat(nx, ny, strength) {
    var cx = nx * GRID_W, cy = ny * gridH;
    var radius = GRID_W * 0.11;
    var x0 = Math.max(0, Math.floor(cx - radius * 2));
    var x1 = Math.min(GRID_W - 1, Math.ceil(cx + radius * 2));
    var y0 = Math.max(0, Math.floor(cy - radius * 2));
    var y1 = Math.min(gridH - 1, Math.ceil(cy + radius * 2));

    for (var y = y0; y <= y1; y++) {
      for (var x = x0; x <= x1; x++) {
        var dx = x - cx, dy = y - cy;
        var add = strength * Math.exp(-(dx * dx + dy * dy) / (radius * radius));
        var i = y * GRID_W + x;
        activity[i] = Math.min(1, activity[i] + add);
      }
    }
    hasActivity = true;
  }

  function onPointerMove(e) {
    var ratio = pixelRatio();
    var x = e.clientX * ratio, y = e.clientY * ratio;

    if (lastX !== null) velocity = Math.min(1, Math.max(velocity, Math.hypot(x - lastX, y - lastY) / (60 * ratio)));
    if (smoothX < -999) { smoothX = x; smoothY = y; }

    if (!reduced) {
      var fromX = lastX === null ? x : lastX;
      var fromY = lastX === null ? y : lastY;
      var distance = Math.hypot(x - fromX, y - fromY);
      var stepSize = 0.03 * width;
      var steps = Math.max(1, Math.ceil(distance / stepSize));
      var strength = 0.09 * Math.min(1, distance / (steps * stepSize));

      if (distance > 0.5) {
        for (var i = 1; i <= steps; i++) {
          splat((fromX + (x - fromX) * i / steps) / width, (fromY + (y - fromY) * i / steps) / height, strength);
        }
      }
    }

    mouseX = x; mouseY = y;
    lastX = x; lastY = y;
    pointerInside = true;
  }

  addEventListener('pointermove', onPointerMove, { passive: true });
  addEventListener('mousemove', onPointerMove, { passive: true });
  document.documentElement.addEventListener('mouseenter', function () { pointerInside = true; });
  document.documentElement.addEventListener('mouseleave', function () { pointerInside = false; });
  addEventListener('blur', function () { pointerInside = false; });
  addEventListener('pointerup', function (e) { if (e.pointerType !== 'mouse') pointerInside = false; }, { passive: true });

  function boxBlur(data, N, r) {
    var temp = new Float32Array(N * N);
    var inv = 1 / (2 * r + 1);
    var x, y, k, sum, row;
    function clampIndex(v) { return v < 0 ? 0 : v > N - 1 ? N - 1 : v; }

    for (y = 0; y < N; y++) {
      row = y * N; sum = 0;
      for (k = -r; k <= r; k++) sum += data[row + clampIndex(k)];
      for (x = 0; x < N; x++) {
        temp[row + x] = sum * inv;
        sum += data[row + clampIndex(x + r + 1)] - data[row + clampIndex(x - r)];
      }
    }
    for (x = 0; x < N; x++) {
      sum = 0;
      for (k = -r; k <= r; k++) sum += temp[clampIndex(k) * N + x];
      for (y = 0; y < N; y++) {
        data[y * N + x] = sum * inv;
        sum += temp[clampIndex(y + r + 1) * N + x] - temp[clampIndex(y - r) * N + x];
      }
    }
  }

  function buildFlowMap(N) {
    var small = document.createElement('canvas');
    small.width = small.height = N;
    var smallCtx = small.getContext('2d');
    smallCtx.drawImage(image, 0, 0, N, N);
    var pixels = smallCtx.getImageData(0, 0, N, N).data;
    var gray = new Float32Array(N * N);
    var i, x, y;
    for (i = 0; i < N * N; i++) {
      gray[i] = (0.299 * pixels[4 * i] + 0.587 * pixels[4 * i + 1] + 0.114 * pixels[4 * i + 2]) / 255;
    }

    var xx = new Float32Array(N * N), yy = new Float32Array(N * N), xy = new Float32Array(N * N);
    for (y = 1; y < N - 1; y++) {
      for (x = 1; x < N - 1; x++) {
        i = y * N + x;
        var gx = (gray[i - N + 1] + 2 * gray[i + 1] + gray[i + N + 1]) - (gray[i - N - 1] + 2 * gray[i - 1] + gray[i + N - 1]);
        var gy = (gray[i + N - 1] + 2 * gray[i + N] + gray[i + N + 1]) - (gray[i - N - 1] + 2 * gray[i - N] + gray[i - N + 1]);
        xx[i] = gx * gx; yy[i] = gy * gy; xy[i] = gx * gy;
      }
    }
    [xx, yy, xy].forEach(function (channel) { boxBlur(channel, N, 5); boxBlur(channel, N, 5); });

    var out = new Uint8Array(N * N * 4);
    for (i = 0; i < N * N; i++) {
      var s = xx[i] + yy[i] + 1e-6;
      var weight = Math.min(1, s / 0.04);
      var ex = -(xx[i] - yy[i]) / s * weight;
      var ey = -2 * xy[i] / s * weight;
      out[4 * i]     = Math.max(0, Math.min(255, Math.round((ex * 0.5 + 0.5) * 255)));
      out[4 * i + 1] = Math.max(0, Math.min(255, Math.round((ey * 0.5 + 0.5) * 255)));
      out[4 * i + 2] = 0;
      out[4 * i + 3] = 255;
    }
    return out;
  }

  function createTexture(unit) {
    var texture = gl.createTexture();
    gl.activeTexture(gl.TEXTURE0 + unit);
    gl.bindTexture(gl.TEXTURE_2D, texture);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.LINEAR);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, gl.LINEAR);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, gl.CLAMP_TO_EDGE);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, gl.CLAMP_TO_EDGE);
    return texture;
  }

  function uploadActivity() {
    gl.activeTexture(gl.TEXTURE2);
    gl.texImage2D(gl.TEXTURE_2D, 0, gl.LUMINANCE, GRID_W, gridH, 0, gl.LUMINANCE, gl.UNSIGNED_BYTE, activityBytes);
  }

  // Chỉ chạy WebGL khi hiệu ứng đang bật; tắt thì dừng hẳn vòng lặp để nhẹ máy
  function begin() {
    if (reduced || failed) { canvas.style.display = 'none'; return; }
    canvas.style.display = '';
    try {
      if (!started) {
        started = true;
        startRendering();
      } else if (!loopId) {
        lastFrame = performance.now();
        needsRedraw = true;
        loop();
      }
    } catch (e) { useFallback(e && e.message); }
  }

  function startRendering() {
    createTexture(0);
    var big = document.createElement('canvas');
    big.width = big.height = 2048;
    big.getContext('2d').drawImage(image, 0, 0, 2048, 2048);
    gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGBA, gl.RGBA, gl.UNSIGNED_BYTE, big);

    createTexture(1);
    var FLOW_SIZE = 512;
    gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGBA, FLOW_SIZE, FLOW_SIZE, 0, gl.RGBA, gl.UNSIGNED_BYTE, buildFlowMap(FLOW_SIZE));

    createTexture(2);
    gl.pixelStorei(gl.UNPACK_ALIGNMENT, 1);

    gl.uniform1i(uniform.uTex, 0);
    gl.uniform1i(uniform.uFlow, 1);
    gl.uniform1i(uniform.uAct, 2);
    gl.uniform2f(uniform.uImg, image.naturalWidth, image.naturalHeight);

    lastFrame = performance.now();

    loop = function () {
      if (reduced) { loopId = null; return; }
      loopId = requestAnimationFrame(loop);
      var now = performance.now();
      var dt = Math.min(0.1, Math.max(0.001, (now - lastFrame) / 1000));
      lastFrame = now;

      try {
        smoothX += (mouseX - smoothX) * (1 - Math.exp(-dt * 3.2));
        smoothY += (mouseY - smoothY) * (1 - Math.exp(-dt * 3.2));
        velocity *= Math.exp(-dt * 3.5);
        presence += ((pointerInside && !reduced ? 1 : 0) - presence) * (1 - Math.exp(-dt * 2.2));
        if (presence < 0.002 && !pointerInside) presence = 0;

        if (pointerInside && !reduced) splat(mouseX / width, mouseY / height, 0.3 * dt);

        var shouldDraw = hasActivity || velocity > 0.002 || presence > 0 || needsRedraw;

        if (hasActivity) {
          var fade = Math.exp(-dt / 2.6);
          var smooth = 1 - Math.exp(-dt * 2.2);
          var anyLeft = false;
          for (var i = 0; i < activity.length; i++) {
            var value = activity[i] * fade;
            if (value < 0.0003) value = 0;
            activity[i] = value;

            var smoothed = activitySmooth[i] + (value - activitySmooth[i]) * smooth;
            if (smoothed < 0.0003 && value === 0) smoothed = 0; else anyLeft = true;
            activitySmooth[i] = smoothed;
            activityBytes[i] = Math.min(255, Math.round(smoothed * 255));
          }
          hasActivity = anyLeft;
          uploadActivity();
        } else if (needsRedraw) {
          uploadActivity();
        }

        if (shouldDraw) {
          gl.uniform2f(uniform.uRes, width, height);
          gl.uniform2f(uniform.uMouse, smoothX, smoothY);
          gl.uniform1f(uniform.uT, (now - startTime) / 1000);
          gl.uniform1f(uniform.uVel, presence);
          gl.drawArrays(gl.TRIANGLE_STRIP, 0, 4);
          needsRedraw = hasActivity || velocity > 0.002 || presence > 0;
          if (gl.isContextLost()) useFallback('mất ngữ cảnh WebGL');
        }
      } catch (err) {
        console.warn('Lỗi vòng lặp nền:', err && err.message);
      }
    };
    loop();
  }

  window.addEventListener('fxchange', function () { if (imageReady) begin(); });

  function onImageReady() { imageReady = true; begin(); }

  if (image.complete && image.naturalWidth) {
    onImageReady();
  } else {
    image.onload = onImageReady;
    image.onerror = function () { useFallback('ảnh nền không tải được'); };
  }
})();

;

/* ===== js/nav.js ===== */
(function () {
  var nav = $('nav');
  var burger = $('#burger');

  function setOpen(open) {
    nav.classList.toggle('open', open);
    burger.setAttribute('aria-expanded', open);
    burger.setAttribute('aria-label', open ? 'Đóng menu' : 'Mở menu');
  }

  burger.addEventListener('click', function () {
    setOpen(!nav.classList.contains('open'));
  });

  $('#menu').addEventListener('click', function (e) {
    if (e.target.closest('a')) setOpen(false);
  });
  addEventListener('keydown', function (e) {
    if (e.key === 'Escape') setOpen(false);
  });

  var linkById = {};
  $$('#menu a').forEach(function (link) {
    linkById[link.getAttribute('href').slice(1)] = link;
  });

  var observer = new IntersectionObserver(function (entries) {
    entries.forEach(function (entry) {
      if (!entry.isIntersecting) return;
      Object.keys(linkById).forEach(function (id) { linkById[id].classList.remove('act'); });
      var current = linkById[entry.target.id];
      if (current) current.classList.add('act');
    });
  }, { rootMargin: '-45% 0px -50% 0px' });

  Object.keys(linkById).forEach(function (id) {
    var section = document.getElementById(id);
    if (section) observer.observe(section);
  });
})();

;

/* ===== js/smooth-scroll.js ===== */
(function () {
  var MIN_DURATION = 700;   // thời gian cuộn tối thiểu (ms)
  var MAX_DURATION = 1500;  // thời gian cuộn tối đa (ms)
  var MS_PER_PIXEL = 0.6;   // đi càng xa thì cuộn càng lâu

  var frameId = null;

  // Bắt đầu chậm, giữa nhanh, cuối chậm dần
  function easeInOutCubic(t) {
    return t < 0.5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2;
  }

  // Khoảng chừa cho thanh menu cố định phía trên (lấy từ scroll-padding-top trong CSS)
  function headerOffset() {
    return parseFloat(getComputedStyle(document.documentElement).scrollPaddingTop) || 0;
  }

  function stop() {
    if (frameId) cancelAnimationFrame(frameId);
    frameId = null;
  }

  function scrollToY(targetY) {
    stop();

    var maxY = document.documentElement.scrollHeight - innerHeight;
    var endY = Math.max(0, Math.min(targetY, maxY));
    var startY = window.scrollY;
    var distance = endY - startY;

    if (reduced || !distance) {
      window.scrollTo(0, endY);
      return;
    }

    var duration = Math.min(MAX_DURATION, Math.max(MIN_DURATION, Math.abs(distance) * MS_PER_PIXEL));
    var startTime = performance.now();

    function step(now) {
      var progress = Math.min(1, (now - startTime) / duration);
      window.scrollTo(0, startY + distance * easeInOutCubic(progress));
      frameId = progress < 1 ? requestAnimationFrame(step) : null;
    }
    frameId = requestAnimationFrame(step);
  }

  // Cho file khác (nút lên đầu trang) dùng chung
  window.scrollToY = scrollToY;

  // Bấm vào bất kỳ liên kết #mục nào cũng cuộn mượt tới đó
  document.addEventListener('click', function (e) {
    var link = e.target.closest('a[href^="#"]');
    if (!link) return;

    var id = decodeURIComponent(link.getAttribute('href').slice(1));
    var target = id && document.getElementById(id);
    if (!target) return;

    e.preventDefault();
    var y = id === 'top' ? 0 : target.getBoundingClientRect().top + window.scrollY - headerOffset();
    scrollToY(y);
    history.replaceState(history.state, '', '#' + id);
  });

  // Người dùng tự cuộn thì dừng hiệu ứng, không giành quyền điều khiển
  ['wheel', 'touchstart', 'keydown'].forEach(function (type) {
    addEventListener(type, stop, { passive: true });
  });
})();

;

/* ===== js/frame.js ===== */
(function () {
  const STAYS_WHERE_DROPPED = false;

  const WIRE_LENGTH = 130;
  const NAIL_Y = 16;
  const SPRING = 30;
  const FRICTION = 3.2;
  const KEY_PUSH = 700;
  const MAX_TILT = 0.6;
  const SVG_NS = 'http://www.w3.org/2000/svg';

  const area = $('#lan');
  const frame = $('#hang');
  if (!area || !frame) return;

  const wireLeft = createWire();
  const wireRight = createWire();
  frame.style.top = WIRE_LENGTH + 'px';

  let x = 0, y = 0;
  let velocityX = 0, velocityY = 0;
  let targetX = 0, targetY = 0;
  let grabOffsetX = 0, grabOffsetY = 0;
  let wobble = 0;
  let dragging = false;
  let running = false;
  let lastTime = 0;
  let areaWidth, areaHeight, frameWidth, frameHeight;
  let limitX, limitTop, limitBottom, restWireLength;

  function createWire() {
    const path = document.createElementNS(SVG_NS, 'path');
    return path;
  }

  const svg = document.createElementNS(SVG_NS, 'svg');
  svg.setAttribute('class', 'wire-svg');
  svg.setAttribute('aria-hidden', 'true');
  svg.appendChild(wireLeft);
  svg.appendChild(wireRight);
  area.insertBefore(svg, area.firstChild);

  function clamp(value, min, max) {
    return Math.min(max, Math.max(min, value));
  }

  function measure() {
    areaWidth = area.clientWidth;
    areaHeight = area.clientHeight;
    frameWidth = frame.offsetWidth;
    frameHeight = frame.offsetHeight;
    limitX = Math.max(0, (areaWidth - frameWidth) / 2 - 4);
    limitTop = -(WIRE_LENGTH - 46);
    limitBottom = Math.max(0, areaHeight - WIRE_LENGTH - frameHeight - 34);
    restWireLength = Math.hypot(frameWidth / 2 - 4, WIRE_LENGTH + 4 - NAIL_Y);
  }

  function drawWire(path, fromX, fromY, toX, toY) {
    const slack = Math.max(0, restWireLength - Math.hypot(toX - fromX, toY - fromY)) * 1.1;
    const midX = (fromX + toX) / 2;
    const midY = (fromY + toY) / 2 + slack;
    path.setAttribute('d', 'M' + fromX.toFixed(1) + ' ' + fromY + 'Q' + midX.toFixed(1) + ' ' + midY.toFixed(1) + ' ' + toX.toFixed(1) + ' ' + toY.toFixed(1));
  }

  function draw(now) {
    const idleSway = reduced ? 0 : 0.018 * Math.sin((now || 0) / 1300);
    const pendulum = -Math.atan2(x, WIRE_LENGTH + y - NAIL_Y) * 0.55;
    const angle = clamp(pendulum + wobble + idleSway, -MAX_TILT, MAX_TILT);

    frame.style.transform =
      'translateX(calc(-50% + ' + x.toFixed(2) + 'px)) translateY(' + y.toFixed(2) + 'px) rotate(' + angle.toFixed(4) + 'rad)';

    const centerX = areaWidth / 2 + x;
    const topY = WIRE_LENGTH + y;
    const halfSpan = frameWidth / 2 - 4;
    const cos = Math.cos(angle);
    const sin = Math.sin(angle);
    const nailX = areaWidth / 2;

    drawWire(wireLeft, nailX, NAIL_Y, centerX - halfSpan * cos - 4 * sin, topY - halfSpan * sin + 4 * cos);
    drawWire(wireRight, nailX, NAIL_Y, centerX + halfSpan * cos - 4 * sin, topY + halfSpan * sin + 4 * cos);
  }

  function bounceOffLimits() {
    if (x > limitX) { x = limitX; velocityX *= -0.3; }
    else if (x < -limitX) { x = -limitX; velocityX *= -0.3; }
    if (y > limitBottom) { y = limitBottom; velocityY *= -0.3; }
    else if (y < limitTop) { y = limitTop; velocityY *= -0.3; }
  }

  function step(now) {
    const dt = Math.min(0.033, (now - lastTime) / 1000) || 0.016;
    lastTime = now;
    const previousX = x, previousY = y;

    if (dragging) {
      const follow = 1 - Math.exp(-dt * 28);
      x += (targetX - x) * follow;
      y += (targetY - y) * follow;
      velocityX = velocityX * 0.6 + ((x - previousX) / dt) * 0.4;
      velocityY = velocityY * 0.6 + ((y - previousY) / dt) * 0.4;
    } else {
      if (STAYS_WHERE_DROPPED) {
        velocityX *= Math.exp(-dt * 3);
        velocityY *= Math.exp(-dt * 3);
      } else {
        velocityX += (-SPRING * x - FRICTION * velocityX) * dt;
        velocityY += (-SPRING * y - FRICTION * velocityY) * dt;
      }
      x += velocityX * dt;
      y += velocityY * dt;
      bounceOffLimits();
    }

    const lag = clamp(velocityX * 0.00045, -0.35, 0.35);
    wobble += (lag - wobble) * (1 - Math.exp(-dt * 7));

    draw(now);
    if (running) requestAnimationFrame(step);
  }

  function run() {
    if (running || reduced) return;
    running = true;
    lastTime = performance.now();
    requestAnimationFrame(step);
  }

  function stop() {
    running = false;
  }

  function release() {
    if (!dragging) return;
    dragging = false;
    frame.classList.remove('drag');
    velocityX = clamp(velocityX, -2500, 2500);
    velocityY = clamp(velocityY, -2500, 2500);
    if (reduced && !STAYS_WHERE_DROPPED) {
      x = y = 0;
      draw(0);
    }
  }

  frame.addEventListener('pointerdown', function (e) {
    measure();
    dragging = true;
    frame.classList.add('drag');
    frame.setPointerCapture(e.pointerId);
    grabOffsetX = e.clientX - x;
    grabOffsetY = e.clientY - y;
    targetX = x;
    targetY = y;
    run();
    e.preventDefault();
  });

  frame.addEventListener('pointermove', function (e) {
    if (!dragging) return;
    targetX = clamp(e.clientX - grabOffsetX, -limitX, limitX);
    targetY = clamp(e.clientY - grabOffsetY, limitTop, limitBottom);
    if (reduced) {
      x = targetX;
      y = targetY;
      draw(0);
    }
  });

  frame.addEventListener('pointerup', release);
  frame.addEventListener('pointercancel', release);

  const KEY_DIRECTIONS = {
    ArrowLeft: [-1, 0],
    ArrowRight: [1, 0],
    ArrowUp: [0, -1],
    ArrowDown: [0, 1]
  };

  frame.addEventListener('keydown', function (e) {
    const direction = KEY_DIRECTIONS[e.key];
    if (!direction) return;
    e.preventDefault();
    measure();

    if (reduced) {
      x = clamp(x + direction[0] * 40, -limitX, limitX);
      y = clamp(y + direction[1] * 40, limitTop, limitBottom);
      draw(0);
      return;
    }
    velocityX += direction[0] * KEY_PUSH;
    velocityY += direction[1] * KEY_PUSH;
    run();
  });

  addEventListener('resize', function () {
    measure();
    x = clamp(x, -limitX, limitX);
    y = clamp(y, limitTop, limitBottom);
    draw(performance.now());
  });

  new IntersectionObserver(function (entries) {
    if (entries[0].isIntersecting) run(); else stop();
  }, { threshold: 0 }).observe(area);

  window.addEventListener('fxchange', function () {
    measure();
    if (reduced) {
      running = false;
      dragging = false;
      frame.classList.remove('drag');
      x = y = velocityX = velocityY = wobble = 0;
      draw(0);
    } else {
      var box = area.getBoundingClientRect();
      if (box.bottom > 0 && box.top < innerHeight) run();
    }
  });

  measure();
  draw(0);
})();

;

/* ===== js/reveal.js ===== */
(function () {
  var SHOW_RATIO = 0.12;     // phần khối lộ ra bao nhiêu thì bắt đầu hiện
  var STAGGER_STEP = 0.12;   // độ trễ giữa các khối cùng hàng (giây)

  function countUp(el) {
    var target = Number(el.dataset.n) || 0;
    var suffix = el.dataset.s || '';
    var startTime = performance.now();

    if (reduced || !target) {
      el.textContent = target + suffix;
      return;
    }

    (function step(now) {
      var progress = Math.min(1, (now - startTime) / 1200);
      var eased = 1 - Math.pow(1 - progress, 3);
      el.textContent = Math.round(target * eased) + suffix;
      if (progress < 1) requestAnimationFrame(step);
    })(startTime);
  }

  window.animateBars = function (root) {
    requestAnimationFrame(function () {
      requestAnimationFrame(function () {
        $$('.bar', root).forEach(function (bar) { bar.classList.add('go'); });
      });
    });
  };

  function show(block) {
    block.classList.add('on');
    $$('[data-n]', block).forEach(countUp);
    window.animateBars(block);
  }

  // Ẩn lại khi ra khỏi màn hình để lần cuộn sau (lên hoặc xuống) hiện lại từ đầu
  function hide(block) {
    block.classList.remove('on');
    $$('.bar', block).forEach(function (bar) { bar.classList.remove('go'); });
  }

  // Các khối cùng cha hiện lần lượt thay vì cùng lúc
  $$('.fade').forEach(function (el) {
    var index = $$('.fade', el.parentElement).indexOf(el);
    el.style.setProperty('--delay', (index * STAGGER_STEP).toFixed(2) + 's');
  });

  var observer = new IntersectionObserver(function (entries) {
    entries.forEach(function (entry) {
      if (entry.isIntersecting && entry.intersectionRatio >= SHOW_RATIO) show(entry.target);
      else if (!entry.isIntersecting) hide(entry.target);
    });
  }, { threshold: [0, SHOW_RATIO] });

  $$('.fade').forEach(function (el) { observer.observe(el); });
})();

;

/* ===== js/tabs.js ===== */
(function () {
  var ALL = 'Tất cả';

  $$('.tabs').forEach(function (tabs) {
    var list = $(tabs.dataset.target);
    if (!list) return;

    var buttons = $$('button', tabs);
    var items = $$('[data-cat]', list);

    function applyFilter(category) {
      buttons.forEach(function (button) {
        var selected = button.dataset.filter === category;
        button.classList.toggle('on', selected);
        button.setAttribute('aria-selected', selected);
      });

      items.forEach(function (item) {
        var visible = category === ALL || item.dataset.cat === category;
        item.hidden = !visible;
        if (visible && item.resetPaint) item.resetPaint();
      });

      $$('.bar', list).forEach(function (bar) { bar.classList.remove('go'); });
      window.animateBars(list);
    }

    tabs.addEventListener('click', function (e) {
      var button = e.target.closest('button');
      if (button) applyFilter(button.dataset.filter);
    });
  });
})();

;

/* ===== js/project-modal.js ===== */
(function () {
  var modal = $('#detail');
  var cards = $$('.card[data-project]');
  var lastFocused = null;

  function indexOfProject(id) {
    for (var i = 0; i < cards.length; i++) {
      if (cards[i].dataset.project === id) return i;
    }
    return -1;
  }

  function titleOf(card) {
    return $('h3', card).textContent;
  }

  function makeButton(label, onClick) {
    var button = document.createElement('button');
    button.className = 'back';
    button.textContent = label;
    button.addEventListener('click', onClick);
    return button;
  }

  function render(i) {
    var card = cards[i];
    var inner = document.createElement('div');
    inner.className = 'detail-in';

    inner.appendChild(makeButton('← Quay lại dự án', closeProject));
    inner.appendChild($('template', card).content.cloneNode(true));

    var pager = document.createElement('div');
    pager.className = 'pn';
    pager.appendChild(i > 0
      ? makeButton('← ' + titleOf(cards[i - 1]), function () { openProject(cards[i - 1].dataset.project, false, true); })
      : document.createElement('span'));
    pager.appendChild(i < cards.length - 1
      ? makeButton(titleOf(cards[i + 1]) + ' →', function () { openProject(cards[i + 1].dataset.project, false, true); })
      : document.createElement('span'));
    inner.appendChild(pager);

    modal.innerHTML = '';
    modal.appendChild(inner);
    modal.scrollTop = 0;
  }

  function show(id) {
    var i = indexOfProject(id);
    if (i < 0) { hide(); return; }

    if (modal.hidden) lastFocused = document.activeElement;
    render(i);
    modal.hidden = false;
    document.documentElement.classList.add('lock');
    document.body.classList.add('lock');
    $('.back', modal).focus({ preventScroll: true });
  }

  function hide() {
    if (modal.hidden) return;
    modal.hidden = true;
    document.documentElement.classList.remove('lock');
    document.body.classList.remove('lock');
    if (lastFocused && lastFocused.focus) lastFocused.focus({ preventScroll: true });
  }

  function openProject(id, push, replace) {
    if (push) history.pushState({ project: id }, '', '#du-an/' + id);
    else if (replace) history.replaceState({ project: id }, '', '#du-an/' + id);
    show(id);
  }

  function closeProject() {
    if (history.state && history.state.project) history.back();
    else hide();
  }

  cards.forEach(function (card) {
    card.addEventListener('click', function () { openProject(card.dataset.project, true); });
    card.addEventListener('keydown', function (e) {
      if (e.key === 'Enter' || e.key === ' ') {
        e.preventDefault();
        openProject(card.dataset.project, true);
      }
    });
  });

  function projectIdFromHash() {
    var match = /^#du-an\/(.+)$/.exec(location.hash);
    return match ? decodeURIComponent(match[1]) : null;
  }

  addEventListener('popstate', function () {
    var id = projectIdFromHash();
    if (id) show(id); else hide();
  });

  addEventListener('keydown', function (e) {
    if (e.key === 'Escape' && !modal.hidden) closeProject();
  });

  var initialId = projectIdFromHash();
  if (initialId) show(initialId);
})();

;

/* ===== js/paint-reveal.js ===== */
(function () {
  var tip = $('#project-tip');
  var TIP_MOUSE = tip ? tip.textContent : '';
  var TIP_TOUCH = '✦ Chạm vào mỗi thẻ để xem chi tiết dự án ✦';
  var TIP_FINGER = '✦ Dùng ngón tay lau lớp sơn, rồi chạm vào thẻ để xem chi tiết ✦';

  var PAINT_COLORS = ['#1e3a8a', '#2a4a9a', '#0f1e4a', '#f9d71c', '#f5e6a8', '#8ab4f8'];
  var BRUSH_RADIUS = finePointer ? 34 : 46;
  var COVER_OPACITY = 0.82;
  var CLEAR_RATIO = finePointer ? 0.8 : 0.7;
  var AUTO_REVEAL_DELAY = 500;

  // Điện thoại / máy tính bảng không có chuột để "rê cọ" → lớp sơn tự tan khi thẻ hiện ra
  var autoReveal = false; // không tự tan nữa: ngón tay lau dần như chuột

  function updateTip() {
    if (tip) tip.textContent = reduced ? TIP_TOUCH : (finePointer ? TIP_MOUSE : TIP_FINGER);
  }

  var cards = $$('[data-reveal]');
  var revealObserver = null;

  if (autoReveal && 'IntersectionObserver' in window) {
    revealObserver = new IntersectionObserver(function (entries) {
      entries.forEach(function (entry) {
        if (!entry.isIntersecting) return;
        revealObserver.unobserve(entry.target);
        setTimeout(function () { if (entry.target.clearPaint) entry.target.clearPaint(); }, AUTO_REVEAL_DELAY);
      });
    }, { threshold: 0.35 });
  }

  cards.forEach(function (card) {
    var canvas = $('.paint-layer', card);
    var ctx = canvas.getContext('2d', { willReadFrequently: true });
    var lastX = null, lastY = null;
    var moveCount = 0;
    var cleared = false;
    var paintedW = 0, paintedH = 0;

    function clearPaint() {
      cleared = true;
      canvas.style.opacity = 0;
      canvas.style.pointerEvents = 'none';
    }

    function paintCover() {
      if (cleared) return;

      // Tắt hiệu ứng → không phủ sơn, xem thẳng nội dung
      if (reduced) { canvas.style.display = 'none'; return; }
      canvas.style.display = '';

      var rect = card.getBoundingClientRect();
      var w = Math.round(rect.width), h = Math.round(rect.height);
      if (!w || !h) return;

      // Trên điện thoại, thanh địa chỉ co giãn làm sự kiện resize bắn liên tục:
      // chỉ vẽ lại khi kích thước thẻ thật sự đổi
      if (w === paintedW && h === paintedH) return;
      paintedW = w; paintedH = h;

      var ratio = Math.min(devicePixelRatio || 1, 2);
      canvas.width = w * ratio;
      canvas.height = h * ratio;
      ctx.setTransform(ratio, 0, 0, ratio, 0, 0);
      ctx.globalCompositeOperation = 'source-over';

      var gradient = ctx.createLinearGradient(0, 0, w, h);
      gradient.addColorStop(0, '#0a1128');
      gradient.addColorStop(0.5, '#142a5e');
      gradient.addColorStop(1, '#0a1128');
      ctx.fillStyle = gradient;
      ctx.globalAlpha = COVER_OPACITY;
      ctx.fillRect(0, 0, w, h);

      for (var i = 0; i < 90; i++) {
        var x = Math.random() * w;
        var y = Math.random() * h;
        var length = 30 + Math.random() * 80;
        var angle = Math.random() * 6.28;

        ctx.strokeStyle = PAINT_COLORS[Math.random() * PAINT_COLORS.length | 0];
        ctx.globalAlpha = 0.2 + Math.random() * 0.4;
        ctx.lineWidth = 2 + Math.random() * 6;
        ctx.lineCap = 'round';
        ctx.beginPath();
        ctx.moveTo(x, y);
        ctx.quadraticCurveTo(
          x + Math.cos(angle) * length * 0.5,
          y + Math.sin(angle) * length * 0.5 + 10,
          x + Math.cos(angle) * length,
          y + Math.sin(angle) * length
        );
        ctx.stroke();
      }

      ctx.globalAlpha = 0.5;
      ctx.fillStyle = '#f5e6a8';
      ctx.font = 'italic 15px "Playfair Display", serif';
      ctx.textAlign = 'center';
      ctx.fillText(finePointer ? '✦ Rê cọ để khám phá ✦' : '✦ Lau bằng ngón tay ✦', w / 2, h * 0.2);
      ctx.globalAlpha = 1;
    }

    function erase(e) {
      if (cleared || reduced) return;

      var rect = canvas.getBoundingClientRect();
      var x = e.clientX - rect.left;
      var y = e.clientY - rect.top;

      ctx.globalCompositeOperation = 'destination-out';

      var steps = lastX === null ? 0 : Math.max(1, Math.hypot(x - lastX, y - lastY) / 6 | 0);
      for (var i = 0; i <= steps; i++) {
        var t = steps ? i / steps : 0;
        var px = lastX === null ? x : lastX + (x - lastX) * t;
        var py = lastY === null ? y : lastY + (y - lastY) * t;

        var spot = ctx.createRadialGradient(px, py, 0, px, py, BRUSH_RADIUS);
        spot.addColorStop(0, 'rgba(0,0,0,1)');
        spot.addColorStop(0.6, 'rgba(0,0,0,.8)');
        spot.addColorStop(1, 'rgba(0,0,0,0)');
        ctx.fillStyle = spot;
        ctx.beginPath();
        ctx.arc(px, py, BRUSH_RADIUS, 0, 7);
        ctx.fill();
      }
      lastX = x;
      lastY = y;

      if (++moveCount % 12 === 0 && isMostlyCleared()) clearPaint();
    }

    function isMostlyCleared() {
      var pixels = ctx.getImageData(0, 0, canvas.width, canvas.height).data;
      var transparent = 0, total = 0;
      for (var k = 3; k < pixels.length; k += 160) {
        total++;
        if (pixels[k] < 50) transparent++;
      }
      return transparent / total > CLEAR_RATIO;
    }

    // Dùng pointer events (chuột + bút + cảm ứng) thay vì chỉ mousemove
    canvas.addEventListener('pointermove', erase);
    canvas.addEventListener('pointerdown', function () { lastX = lastY = null; });
    canvas.addEventListener('pointerup', function () { lastX = lastY = null; });
    canvas.addEventListener('pointercancel', function () { lastX = lastY = null; });
    canvas.addEventListener('pointerleave', function () { lastX = lastY = null; });

    card.resetPaint = paintCover;
    card.clearPaint = clearPaint;
    paintCover();
    if (revealObserver) revealObserver.observe(card);

    var resizeTimer = null;
    addEventListener('resize', function () {
      clearTimeout(resizeTimer);
      resizeTimer = setTimeout(paintCover, 150);
    });
  });

  window.addEventListener('fxchange', function () {
    cards.forEach(function (card) { card.resetPaint(); });
    updateTip();
  });

  updateTip();
})();

;

/* ===== js/contact-form.js ===== */
(function () {
  var form = $('#contact-form');
  if (!form) return;

  var status = $('#form-status');
  var counter = $('#count');

  function floatBubble(name, text) {
    var layer = $('#bubbles');
    if (!layer) return;
    var bubble = document.createElement('div');
    var who = document.createElement('b');
    var line = document.createElement('p');
    bubble.className = 'bubble';
    bubble.style.setProperty('--x', (8 + Math.random() * 55) + '%');
    bubble.style.setProperty('--drift', (Math.random() * 90 - 45) + 'px');
    who.textContent = name;
    line.textContent = text.length > 140 ? text.slice(0, 140) + '…' : text;
    bubble.appendChild(who);
    bubble.appendChild(line);
    layer.appendChild(bubble);
    setTimeout(function () { bubble.remove(); }, 9500);
  }

  var validators = {
    name: function (value) {
      if (!value) return 'Vui lòng nhập tên của bạn.';
      if (value.length < 2) return 'Tên cần có ít nhất 2 ký tự.';
      return '';
    },
    message: function (value) {
      if (!value) return 'Vui lòng nhập lời nhắn.';
      if (value.length < 10) return 'Lời nhắn cần có ít nhất 10 ký tự.';
      return '';
    }
  };

  function validateField(name) {
    var input = form.elements[name];
    var error = validators[name](input.value.trim());
    var box = input.closest('.field');

    $('.err', box).textContent = error;
    box.classList.toggle('invalid', !!error);
    box.classList.toggle('valid', !error);
    input.setAttribute('aria-invalid', !!error);
    return !error;
  }

  function showStatus(text, isError) {
    status.textContent = text;
    status.classList.toggle('error', !!isError);
  }

  Object.keys(validators).forEach(function (name) {
    var input = form.elements[name];
    input.addEventListener('blur', function () { validateField(name); });
    input.addEventListener('input', function () {
      if (input.closest('.field').classList.contains('invalid')) validateField(name);
    });
  });

  form.elements.message.addEventListener('input', function (e) {
    counter.textContent = e.target.value.length + '/' + e.target.maxLength;
  });

  form.addEventListener('submit', function (e) {
    e.preventDefault();

    var results = Object.keys(validators).map(validateField);
    if (results.indexOf(false) !== -1) {
      showStatus('Vui lòng sửa các ô báo lỗi rồi gửi lại.', true);
      var firstInvalid = $('.field.invalid input, .field.invalid textarea', form);
      if (firstInvalid) firstInvalid.focus();
      return;
    }

    var name = form.elements.name.value.trim();
    var message = form.elements.message.value.trim();

    var subject = 'Liên hệ từ portfolio — ' + name;
    var body = message + '\n\n— ' + name;
    var mailto = 'mailto:' + form.dataset.mailto +
      '?subject=' + encodeURIComponent(subject) +
      '&body=' + encodeURIComponent(body);

    floatBubble(name, message);
    showStatus('✦ Cảm ơn ' + name + '! Lời nhắn của bạn đang bay lên…', false);
    form.reset();
    counter.textContent = '0/' + form.elements.message.maxLength;
    $$('.field', form).forEach(function (box) { box.classList.remove('valid', 'invalid'); });
    setTimeout(function () { window.location.href = mailto; }, 2500);
  });
})();

;

/* ===== js/scroll-top.js ===== */
(function () {
  var button = $('#to-top');
  var SHOW_AFTER = 600;

  function updateVisibility() {
    button.classList.toggle('show', window.scrollY > SHOW_AFTER);
  }

  button.addEventListener('click', function () {
    window.scrollToY(0);
  });

  addEventListener('scroll', updateVisibility, { passive: true });
  updateVisibility();
})();

;

/* ===== js/fx-toggle.js ===== */
(function () {
  var button = $('#fx-toggle');
  if (!button) return;

  function render() {
    button.setAttribute('aria-pressed', fxOn);
    button.setAttribute('aria-label', fxOn ? 'Tắt hiệu ứng để trang nhẹ hơn' : 'Bật hiệu ứng');
    $('.fx-state', button).textContent = fxOn ? 'Bật' : 'Tắt';
  }

  button.addEventListener('click', function () {
    setFx(!fxOn, true);
    render();
  });

  render();
})();


/* ===== js/quiz.js — Bạn là bức tranh nào của Van Gogh? ===== */
(function () {
  var box = $('#quiz-box');
  if (!box) return;

  var P = {
    s: { n: 'Đêm đầy sao', y: '1889', e: '🌌', c: ['#0a1128', '#1e3a8a', '#f9d71c'],
         d: 'Bạn là người mơ mộng và sâu sắc. Ban đêm là lúc đầu óc bạn sáng nhất; bạn nhìn thấy những xoáy năng lượng mà người khác bỏ qua.',
         t: ['Mơ mộng', 'Sâu sắc', 'Sáng tạo'] },
    f: { n: 'Hoa hướng dương', y: '1888', e: '🌻', c: ['#7a4b00', '#e8a317', '#fff2a8'],
         d: 'Bạn ấm áp, tràn năng lượng và luôn hướng về phía ánh sáng. Ở cạnh bạn, mọi người thấy vui và có động lực hơn.',
         t: ['Nhiệt huyết', 'Lạc quan', 'Chân thành'] },
    c: { n: 'Quán cà phê ban đêm', y: '1888', e: '☕', c: ['#0b1b4a', '#2c4aa0', '#ff9b54'],
         d: 'Bạn thích quan sát, thích những nơi ấm áp giữa đêm lạnh. Bạn là người lắng nghe giỏi và có gu riêng rất rõ.',
         t: ['Tinh tế', 'Hòa đồng', 'Quan sát tốt'] },
    w: { n: 'Cánh đồng lúa mì với đàn quạ', y: '1890', e: '🐦‍⬛', c: ['#1b2a5e', '#c99a1a', '#3a2a10'],
         d: 'Bạn nội tâm và cảm xúc dữ dội dù ít nói. Bạn cần không gian riêng để suy nghĩ, và khi đã làm thì làm rất đến nơi đến chốn.',
         t: ['Nội tâm', 'Mạnh mẽ', 'Độc lập'] },
    b: { n: 'Hoa hạnh nhân', y: '1890', e: '🌸', c: ['#5fc7d6', '#a8e2e8', '#fff5f7'],
         d: 'Bạn dịu dàng, hy vọng và luôn bắt đầu điều mới bằng sự nhẹ nhàng. Bạn tin rằng những điều đẹp nhất lớn lên từ rất nhỏ.',
         t: ['Dịu dàng', 'Hy vọng', 'Kiên nhẫn'] }
  };

  var Q = [
    ['Cuối tuần lý tưởng của bạn là?', [['Nằm ngắm sao và nghĩ vẩn vơ', 's'], ['Tụ tập bạn bè, cười thật to', 'f'], ['Ngồi quán quen, ngắm người qua lại', 'c'], ['Một mình đi bộ giữa đồng rộng', 'w']]],
    ['Bạn code tốt nhất khi nào?', [['Khuya, một mình, đầy cảm hứng', 's'], ['Làm dự án thật, đầy năng lượng', 'f'], ['Có nhạc và một ly cà phê', 'c'], ['Có người đồng hành, nhẹ nhàng', 'b']]],
    ['Màu nào làm bạn rung động nhất?', [['Xanh cobalt thăm thẳm', 's'], ['Vàng rực như nắng', 'f'], ['Cam ấm giữa màn đêm', 'c'], ['Xanh ngọc dịu với hồng nhạt', 'b']]],
    ['Gặp lỗi khó sửa, bạn sẽ?', [['Tìm một góc nhìn hoàn toàn mới', 's'], ['Cười, rồi thử cách khác', 'f'], ['Im lặng, nghĩ thật lâu rồi vượt qua', 'w'], ['Nghỉ một chút rồi quay lại', 'b']]],
    ['Bạn mong điều gì ở tương lai?', [['Một khởi đầu mới đầy hy vọng', 'b'], ['Một nơi thật sự thuộc về', 'c'], ['Hiểu rõ chính mình', 'w'], ['Mang niềm vui đến mọi người', 'f']]],
    ['Câu nào giống bạn nhất?', [['Tôi nhìn lên trời để tìm câu trả lời', 's'], ['Tôi thích buổi tối có ánh đèn ấm', 'c'], ['Điều đẹp nhất bắt đầu rất nhỏ', 'b'], ['Tôi ít nói nhưng cảm xúc rất sâu', 'w']]]
  ];

  // Tranh nhúng sẵn (data URI trong window.ART_DATA). "w" (Cánh đồng lúa mì) chưa có ảnh -> dùng nền màu + biểu tượng.
  var ART = window.ART_DATA || {};
  var ORDER = ['s', 'c', 'f', 'b'];
  var score, step;

  function el(html) {
    box.innerHTML = html;
    var b = $('button', box);
    if (b) b.focus({ preventScroll: true });
  }

  function newGame() { score = { s: 0, f: 0, c: 0, w: 0, b: 0 }; step = 0; ask(); }

  function art(key, cls, alt, i) {
    return '<img class="' + cls + '" src="' + ART[key] + '" alt="' + (alt || '') + '" draggable="false"' +
           (i === undefined ? '' : ' style="--i:' + i + '"') + '>';
  }

  /* ---------- Chuyển động chậm theo nét vẽ ----------
     Tranh đứng yên. Mỗi điểm chỉ dịch rất nhẹ dọc theo hướng nét cọ tại điểm đó (hướng lấy từ chính bức tranh),
     pha lệch nhau theo vị trí nên các nét "chảy" thành sóng chậm. Chạy tự động, không cần bấm hay rê chuột. */
  var FLOW_VS = 'attribute vec2 p;void main(){gl_Position=vec4(p,0.,1.);}';
  var FLOW_FS = [
    '#ifdef GL_FRAGMENT_PRECISION_HIGH', 'precision highp float;', '#else', 'precision mediump float;', '#endif',
    'uniform sampler2D uTexA,uFlowA,uTexB,uFlowB;uniform vec2 uRes,uImgA,uImgB;uniform float uT,uMix;',
    'vec3 paint(sampler2D tex,sampler2D flow,vec2 img){',
    ' vec2 f=vec2(gl_FragCoord.x,uRes.y-gl_FragCoord.y);',
    ' vec2 ax=uRes/img;float cv=max(ax.x,ax.y);',
    ' vec2 uv=(f-0.5*uRes)/(img*cv)+0.5;',                                   // phủ kín khung, không méo
    ' vec2 e=texture2D(flow,uv).rg*2.0-1.0;',
    ' float coh=smoothstep(0.04,0.3,length(e));',                            // chỗ nào có nét rõ thì mới chuyển động
    ' float a=atan(e.y,e.x+1e-4)*0.5;vec2 dir=vec2(cos(a),sin(a));',
    ' float ph=dot(uv,vec2(23.0,17.0))+uT*0.45;',
    ' vec2 ed=smoothstep(vec2(0.0),vec2(0.06),uv)*smoothstep(vec2(1.0),vec2(0.94),uv);',  // giữ yên sát mép
    ' float k=coh*ed.x*ed.y;',
    ' vec2 q=uv+dir*k*(0.0050*sin(ph)+0.0025*sin(ph*1.7+uT*0.3));',
    ' return texture2D(tex,q).rgb;}',
    'void main(){',
    ' vec3 c=paint(uTexA,uFlowA,uImgA);',
    ' if(uMix>0.001)c=mix(c,paint(uTexB,uFlowB,uImgB),uMix);',
    ' gl_FragColor=vec4(c,1.0);}'
  ].join('\n');

  var flowCache = {};   // key -> { img, flow } dùng lại giữa các câu hỏi

  // Hướng nét cọ: structure tensor từ độ sáng ảnh, làm mờ vài lần cho mượt. Trả về RGBA 256x256 (r,g = hướng).
  function buildFlow(img, N) {
    var cv = document.createElement('canvas'), x, y, i;
    cv.width = cv.height = N;
    var cx = cv.getContext('2d');
    cx.drawImage(img, 0, 0, N, N);
    var px = cx.getImageData(0, 0, N, N).data, g = new Float32Array(N * N);
    for (i = 0; i < N * N; i++) g[i] = (0.299 * px[4 * i] + 0.587 * px[4 * i + 1] + 0.114 * px[4 * i + 2]) / 255;

    var xx = new Float32Array(N * N), yy = new Float32Array(N * N), xy = new Float32Array(N * N);
    for (y = 1; y < N - 1; y++) for (x = 1; x < N - 1; x++) {
      i = y * N + x;
      var gx = (g[i - N + 1] + 2 * g[i + 1] + g[i + N + 1]) - (g[i - N - 1] + 2 * g[i - 1] + g[i + N - 1]);
      var gy = (g[i + N - 1] + 2 * g[i + N] + g[i + N + 1]) - (g[i - N - 1] + 2 * g[i - N] + g[i - N + 1]);
      xx[i] = gx * gx; yy[i] = gy * gy; xy[i] = gx * gy;
    }
    [xx, yy, xy].forEach(function (ch) {
      for (var pass = 0; pass < 4; pass++) {
        var tmp = new Float32Array(N * N);
        for (var yy2 = 1; yy2 < N - 1; yy2++) for (var xx2 = 1; xx2 < N - 1; xx2++) {
          var k = yy2 * N + xx2, sum = 0;
          for (var oy = -1; oy <= 1; oy++) for (var ox = -1; ox <= 1; ox++) sum += ch[k + oy * N + ox];
          tmp[k] = sum / 9;
        }
        ch.set(tmp);
      }
    });

    var out = new Uint8Array(N * N * 4);
    function byte(v) { return Math.max(0, Math.min(255, Math.round((v * 0.5 + 0.5) * 255))); }
    for (i = 0; i < N * N; i++) {
      var s = xx[i] + yy[i] + 1e-6, w = Math.min(1, s / 0.04);
      out[4 * i] = byte(-(xx[i] - yy[i]) / s * w);
      out[4 * i + 1] = byte(-2 * xy[i] / s * w);
      out[4 * i + 3] = 255;
    }
    return out;
  }

  function loadArt(key, done) {
    var c = flowCache[key];
    if (c) { done(c); return; }
    var im = new Image();
    im.onload = function () { flowCache[key] = { img: im, flow: buildFlow(im, 256) }; done(flowCache[key]); };
    im.onerror = function () { done(null); };
    im.src = ART[key];
  }

  // Phủ canvas WebGL lên khung `holder`. Nhiều tranh thì chuyển mờ lần lượt (mỗi tranh HOLD giây).
  function animateArt(holder, keys) {
    if (!holder || !fxOn) return;                                  // tắt hiệu ứng -> giữ ảnh tĩnh
    keys = keys.filter(function (k) { return ART[k]; });
    if (!keys.length) return;

    var cv = document.createElement('canvas'), gl = null;
    try { gl = cv.getContext('webgl', { antialias: false, alpha: false }) || cv.getContext('experimental-webgl'); } catch (e) {}
    if (!gl) return;
    cv.className = 'art-gl';

    var loaded = [], pending = keys.length;
    keys.forEach(function (k, idx) {
      loadArt(k, function (d) { loaded[idx] = d; if (--pending === 0) start(); });
    });

    function start() {
      if (!document.body.contains(holder) || loaded.some(function (d) { return !d; })) return;
      try {
        var prog = makeProgram(gl);
        var texs = loaded.map(function (d) {
          return { t: makeTexture(gl, function () { gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGBA, gl.RGBA, gl.UNSIGNED_BYTE, d.img); }),
                   f: makeTexture(gl, function () { gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGBA, 256, 256, 0, gl.RGBA, gl.UNSIGNED_BYTE, d.flow); }),
                   w: d.img.naturalWidth, h: d.img.naturalHeight };
        });
        var U = {};
        ['uTexA', 'uFlowA', 'uTexB', 'uFlowB', 'uRes', 'uImgA', 'uImgB', 'uT', 'uMix'].forEach(function (n) { U[n] = gl.getUniformLocation(prog, n); });
        gl.uniform1i(U.uTexA, 0); gl.uniform1i(U.uFlowA, 1); gl.uniform1i(U.uTexB, 2); gl.uniform1i(U.uFlowB, 3);

        holder.appendChild(cv);
        var t0 = performance.now(), w = 0, h = 0, shown = false, HOLD = 5, FADE = 1.3;

        (function frame() {
          if (!document.body.contains(cv)) {                       // đã sang câu khác / chơi lại -> giải phóng WebGL
            var lose = gl.getExtension('WEBGL_lose_context');
            if (lose) lose.loseContext();
            return;
          }
          if (!fxOn) { holder.classList.remove('gl-on'); cv.style.display = 'none'; return; }

          var ratio = Math.min(devicePixelRatio || 1, 1.5);
          var cw = Math.max(2, Math.round(cv.clientWidth * ratio)), ch = Math.max(2, Math.round(cv.clientHeight * ratio));
          if (cw !== w || ch !== h) { w = cv.width = cw; h = cv.height = ch; gl.viewport(0, 0, w, h); }

          var t = (performance.now() - t0) / 1000, n = texs.length, i = 0, mix = 0;
          if (n > 1) {
            var slot = Math.floor(t / HOLD), into = t - slot * HOLD;
            i = slot % n;
            mix = Math.max(0, Math.min(1, (into - (HOLD - FADE)) / FADE));
            mix = mix * mix * (3 - 2 * mix);
          }
          var a = texs[i], b = texs[(i + 1) % n];
          [a.t, a.f, b.t, b.f].forEach(function (tex, unit) { gl.activeTexture(gl.TEXTURE0 + unit); gl.bindTexture(gl.TEXTURE_2D, tex); });
          gl.uniform2f(U.uImgA, a.w, a.h); gl.uniform2f(U.uImgB, b.w, b.h);
          gl.uniform2f(U.uRes, w, h); gl.uniform1f(U.uT, t); gl.uniform1f(U.uMix, mix);
          gl.drawArrays(gl.TRIANGLE_STRIP, 0, 4);

          if (!shown) { shown = true; holder.classList.add('gl-on'); }   // ẩn ảnh tĩnh khi canvas đã vẽ khung đầu
          requestAnimationFrame(frame);
        })();
      } catch (err) {
        console.warn('Chuyển động tranh tắt, dùng ảnh tĩnh:', err && err.message);
        if (cv.parentNode) cv.parentNode.removeChild(cv);
      }
    }
  }

  function makeShader(gl, type, code) {
    var sh = gl.createShader(type);
    gl.shaderSource(sh, code);
    gl.compileShader(sh);
    if (!gl.getShaderParameter(sh, gl.COMPILE_STATUS)) throw new Error(gl.getShaderInfoLog(sh));
    return sh;
  }

  function makeProgram(gl) {
    var prog = gl.createProgram();
    gl.attachShader(prog, makeShader(gl, gl.VERTEX_SHADER, FLOW_VS));
    gl.attachShader(prog, makeShader(gl, gl.FRAGMENT_SHADER, FLOW_FS));
    gl.linkProgram(prog);
    if (!gl.getProgramParameter(prog, gl.LINK_STATUS)) throw new Error('Không liên kết được shader');
    gl.useProgram(prog);
    gl.bindBuffer(gl.ARRAY_BUFFER, gl.createBuffer());
    gl.bufferData(gl.ARRAY_BUFFER, new Float32Array([-1, -1, 1, -1, -1, 1, 1, 1]), gl.STATIC_DRAW);
    var loc = gl.getAttribLocation(prog, 'p');
    gl.enableVertexAttribArray(loc);
    gl.vertexAttribPointer(loc, 2, gl.FLOAT, false, 0, 0);
    return prog;
  }

  function makeTexture(gl, upload) {
    var t = gl.createTexture();
    gl.bindTexture(gl.TEXTURE_2D, t);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.LINEAR);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, gl.LINEAR);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, gl.CLAMP_TO_EDGE);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, gl.CLAMP_TO_EDGE);
    upload();
    return t;
  }

  /* ---------- Các màn hình ---------- */
  function intro() {
    var saved = null;
    try { saved = localStorage.getItem('portfolio-quiz'); } catch (e) {}
    el('<div class="q-stage q-slides" aria-hidden="true">' + ORDER.map(function (k, i) { return art(k, 'q-img', '', i); }).join('') + '</div>' +
       '<p class="q-n">Mini game · 6 câu · 1 phút</p><h3>Bạn hợp với bức tranh nào?</h3>' +
       '<p class="q-intro">Trả lời nhanh theo trực giác, mình sẽ cho bạn biết tính cách của bạn giống tác phẩm nào của Van Gogh.' +
       (saved && P[saved] ? '<br>Lần trước bạn là: <b>' + P[saved].n + '</b>.' : '') + '</p>' +
       '<button class="btn fill" id="q-start" type="button">Bắt đầu ✦</button>');
    animateArt($('.q-stage', box), ORDER);
    $('#q-start').addEventListener('click', newGame);
  }

  function ask() {
    var q = Q[step], key = ORDER[step % ORDER.length];
    el('<div class="q-stage" aria-hidden="true">' + art(key, 'q-img') + '</div>' +
       '<div class="q-prog" role="progressbar" aria-valuemin="0" aria-valuemax="' + Q.length + '" aria-valuenow="' + step + '"><i style="width:' + (step / Q.length * 100) + '%"></i></div>' +
       '<p class="q-n">Câu ' + (step + 1) + ' / ' + Q.length + '</p><h3>' + q[0] + '</h3><div class="qopts">' +
       q[1].map(function (a) { return '<button class="qopt" type="button" data-k="' + a[1] + '">' + a[0] + '</button>'; }).join('') + '</div>');
    animateArt($('.q-stage', box), [key]);
    $$('.qopt', box).forEach(function (b) {
      b.addEventListener('click', function () {
        score[b.dataset.k]++;
        step++;
        if (step < Q.length) ask(); else result();
      });
    });
  }

  function result() {
    var keys = Object.keys(P).sort(function (a, b) { return score[b] - score[a]; });
    var wk = keys[0], win = P[wk], hasImg = !!ART[wk];
    try { localStorage.setItem('portfolio-quiz', wk); } catch (e) {}

    var rows = keys.slice(0, 3).map(function (k) {
      var pct = Math.round(score[k] / Q.length * 100);
      return '<div><span>' + P[k].n + '</span><i><b style="width:' + pct + '%"></b></i><span>' + pct + '%</span></div>';
    }).join('');

    el('<div class="qres"><div class="qart' + (hasImg ? ' has-img' : '') + '" style="--c1:' + win.c[0] + ';--c2:' + win.c[1] + ';--c3:' + win.c[2] + '">' +
       (hasImg ? art(wk, 'qart-img', 'Tranh ' + win.n + ' của Van Gogh') + '<div class="qart-shade" aria-hidden="true"></div>' : '') +
       '<div class="qart-in">' + (hasImg ? '' : '<div class="em" aria-hidden="true">' + win.e + '</div>') +
       '<small>Bạn giống bức tranh</small><h3>' + win.n + '</h3><small>Van Gogh · ' + win.y + '</small></div></div>' +
       '<p>' + win.d + '</p><ul class="chips">' + win.t.map(function (t) { return '<li class="chip">' + t + '</li>'; }).join('') + '</ul>' +
       '<div class="qmatch" aria-label="Độ hợp với các bức tranh">' + rows + '</div></div>' +
       '<div class="cta"><button class="btn fill" id="q-again" type="button">Chơi lại</button><button class="btn" id="q-copy" type="button">Sao chép kết quả</button></div>' +
       '<p class="form-status" id="q-msg" role="status"></p>');

    if (hasImg) animateArt($('.qart', box), [wk]);
    $('#q-again').addEventListener('click', newGame);
    $('#q-copy').addEventListener('click', function () {
      var text = 'Mình giống bức tranh “' + win.n + '” của Van Gogh! Thử xem bạn là bức nào nhé ✦';
      var done = function (ok) { $('#q-msg').textContent = ok ? '✦ Đã sao chép!' : text; };
      try { navigator.clipboard.writeText(text).then(function () { done(true); }, function () { done(false); }); } catch (e) { done(false); }
    });
  }

  intro();
})();

/* ===== js/extras.js — thanh tiến độ cuộn ===== */
(function () {
  var bar = $('#paint-progress i');
  var ticking = false;

  function update() {
    var max = document.documentElement.scrollHeight - innerHeight;
    bar.style.transform = 'scaleX(' + (max > 0 ? Math.min(1, scrollY / max) : 0) + ')';
    ticking = false;
  }
  addEventListener('scroll', function () { if (!ticking) { ticking = true; requestAnimationFrame(update); } }, { passive: true });
  update();

})();

/* ===== js/signature-story.js — ký tên ở cuối trang, bong bóng tròn hiện rồi tan trên nền tối ===== */
(function () {
  var ITEMS = [
    ['Lê Hữu Châu', 'Sinh viên Công nghệ thông tin', 'big'],
    ['Định hướng', 'Khoa Học Dữ Liệu'],
    ['Đại học GTVT / UTH', 'Công nghệ thông tin · 2023 – 2026'],
    ['THPT Hàm Thuận Bắc', '2020 – 2023'],
    ['Mục tiêu', 'Trở thành Kỹ sư Dữ liệu'],
    ['Ngắn hạn · 1 năm', 'Python, SQL và 3 dự án ETL trên GitHub'],
    ['Trung hạn · 2–3 năm', 'Spark, Airflow, nền tảng đám mây'],
    ['Dài hạn · 5 năm', 'Data Engineer có kinh nghiệm'],
    ['Kỹ năng', 'HTML5 · CSS3 · JavaScript · Python · Java'],
    ['Công cụ', 'Git & GitHub · VS Code · Claude · Docker'],
    ['Dự án cá nhân', 'Website Portfolio cá nhân'],
    ['Dự án nhóm', 'Website trung tâm thú y'],
    ['Sở thích', 'Đọc sách · Nghe nhạc · Chơi game · Vẽ phác thảo'],
    ['Liên hệ', 'chau87193@gmail.com · GitHub lechau06'],
    ['Cảm ơn bạn đã ký tên ✦', 'Mong sớm được cùng bạn vẽ nên điều mới', 'big']
  ];

  var timers = [];
  var HOLD = 3600;                       // giữ bao lâu sau khi hiện đủ (ms)
  var GAP = 950; // khoảng cách giữa hai bong bóng

  // Cảnh "SkyNight Flower": đêm sao, bụi cây xanh ngọc, hoa hồng phát sáng trong chuông kính
  function flowerSVG(id) {
    var stars = [[30,26,1.4],[58,14,1],[84,30,1.2],[118,16,1.5],[150,28,1],[172,46,1.3],[40,62,1],[130,52,1.1],[18,84,1.2],[186,80,1],[100,40,.9],[68,48,.9]];
    var st = stars.map(function (a, i) {
      return '<circle class="fl-star" cx="' + a[0] + '" cy="' + a[1] + '" r="' + a[2] + '" fill="#fff" style="animation-delay:' + (i * 0.37).toFixed(2) + 's"/>';
    }).join('');
    return '<svg viewBox="0 0 200 200" xmlns="http://www.w3.org/2000/svg" focusable="false">' +
      '<defs><clipPath id="c' + id + '"><circle cx="100" cy="100" r="98"/></clipPath>' +
      '<linearGradient id="s' + id + '" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#150d3b"/><stop offset=".6" stop-color="#3a2a73"/><stop offset="1" stop-color="#5a3b86"/></linearGradient>' +
      '<radialGradient id="g' + id + '"><stop offset="0" stop-color="#ff5c7c" stop-opacity=".55"/><stop offset="1" stop-color="#ff5c7c" stop-opacity="0"/></radialGradient></defs>' +
      '<g clip-path="url(#c' + id + ')"><rect width="200" height="200" fill="url(#s' + id + ')"/>' + st +
      '<path d="M0 118 Q18 98 40 112 Q58 92 78 116 L78 200 L0 200Z" fill="#1f8a99"/>' +
      '<path d="M122 116 Q142 92 160 110 Q182 96 200 116 L200 200 L122 200Z" fill="#2aa7b3"/>' +
      '<path d="M0 150 Q30 130 60 148 Q100 128 140 148 Q172 130 200 150 L200 200 L0 200Z" fill="#14505e"/>' +
      '<path d="M0 172 Q40 154 80 170 Q120 154 160 170 Q184 160 200 168 L200 200 L0 200Z" fill="#0d3340"/>' +
      '<circle cx="100" cy="102" r="46" fill="url(#g' + id + ')" class="fl-glow"/>' +
      '<path d="M82 156 V94 Q82 62 100 62 Q118 62 118 94 V156Z" fill="rgba(190,225,255,.14)" stroke="rgba(210,235,255,.55)" stroke-width="1.5"/>' +
      '<rect x="78" y="155" width="44" height="4" rx="2" fill="#c0392b"/>' +
      '<path d="M100 150 Q98 128 100 108" stroke="#3aa05a" stroke-width="2.2" fill="none"/>' +
      '<ellipse cx="94" cy="130" rx="7" ry="3.2" fill="#2f8a4c" transform="rotate(-30 94 130)"/>' +
      '<ellipse cx="107" cy="122" rx="6" ry="3" fill="#2f8a4c" transform="rotate(28 107 122)"/>' +
      '<g class="fl-rose"><ellipse cx="100" cy="100" rx="13" ry="12" fill="#d92d55"/><ellipse cx="94" cy="98" rx="7" ry="9" fill="#f04a6f"/>' +
      '<ellipse cx="106" cy="98" rx="7" ry="9" fill="#f04a6f"/><ellipse cx="100" cy="96" rx="6" ry="8" fill="#ff6f8d"/>' +
      '<path d="M97 94 Q100 90 103 94 Q100 99 97 94Z" fill="#c21f48"/></g>' +
      '<ellipse class="fl-petal" cx="96" cy="140" rx="3" ry="1.8" fill="#e63960"/>' +
      '<ellipse class="fl-petal p2" cx="106" cy="144" rx="2.6" ry="1.5" fill="#ff5c7c"/></g>' +
      '<circle cx="100" cy="100" r="98" fill="none" stroke="rgba(249,215,28,.6)" stroke-width="2"/></svg>';
  }

  var openBtn = $('#sign-open');
  if (!openBtn) return;
  openBtn.innerHTML = '<span class="fl-mini" aria-hidden="true">' + flowerSVG('m') + '</span>';

  var dlg = document.createElement('div');
  dlg.id = 'sign';
  dlg.hidden = true;
  dlg.setAttribute('role', 'dialog');
  dlg.setAttribute('aria-modal', 'true');
  dlg.setAttribute('aria-label', 'Ký tên');
  dlg.innerHTML = '<div class="glass sign-box"><h3>Ký tên của bạn</h3>' +
    '<p>Vẽ chữ ký bằng chuột hoặc ngón tay, rồi bấm “Xem hành trình”.</p>' +
    '<canvas id="sign-pad" aria-label="Khung ký tên"></canvas>' +
    '<p class="form-status error" id="sign-msg" role="status"></p>' +
    '<div class="cta"><button class="btn" id="sign-clear" type="button">Xóa</button>' +
    '<button class="btn" id="sign-cancel" type="button">Hủy</button>' +
    '<button class="btn fill" id="sign-go" type="button">Xem hành trình ✦</button></div></div>';
  document.body.appendChild(dlg);

  var story = document.createElement('div');
  story.id = 'story';
  story.hidden = true;
  story.setAttribute('role', 'dialog');
  story.setAttribute('aria-modal', 'true');
  story.setAttribute('aria-label', 'Hành trình của Lê Hữu Châu');
  story.innerHTML = '<div class="st-scene" aria-hidden="true">' + flowerSVG('b') + '</div>' +
    '<div class="st-sky" id="st-sky" aria-hidden="true"></div><div class="st-top"><button class="btn" id="st-close" type="button">Đóng ✕</button></div>' +
    '<ul class="sr-only" id="st-list"></ul>' +
    '<div class="st-field" id="st-field" aria-hidden="true"></div>';
  document.body.appendChild(story);
  $('#st-list').innerHTML = ITEMS.map(function (it) { return '<li>' + it[0] + ': ' + it[1] + '</li>'; }).join('');

  var pad = $('#sign-pad');
  var ctx = pad.getContext('2d');
  var drawing = false, points = 0, lx = 0, ly = 0;

  function sizePad() {
    var r = pad.getBoundingClientRect();
    var ratio = Math.min(devicePixelRatio || 1, 2);
    pad.width = Math.max(1, r.width * ratio);
    pad.height = Math.max(1, r.height * ratio);
    ctx.setTransform(ratio, 0, 0, ratio, 0, 0);
    ctx.lineWidth = 3.2;
    ctx.lineCap = ctx.lineJoin = 'round';
    ctx.strokeStyle = '#f9d71c';
    ctx.shadowColor = 'rgba(249,215,28,.7)';
    ctx.shadowBlur = 6;
    points = 0;
  }
  function pos(e) { var r = pad.getBoundingClientRect(); return [e.clientX - r.left, e.clientY - r.top]; }

  pad.addEventListener('pointerdown', function (e) {
    drawing = true;
    pad.setPointerCapture(e.pointerId);
    var p = pos(e); lx = p[0]; ly = p[1];
    ctx.beginPath(); ctx.moveTo(lx, ly); ctx.lineTo(lx + 0.01, ly); ctx.stroke();
    e.preventDefault();
  });
  pad.addEventListener('pointermove', function (e) {
    if (!drawing) return;
    var p = pos(e);
    ctx.beginPath(); ctx.moveTo(lx, ly); ctx.lineTo(p[0], p[1]); ctx.stroke();
    lx = p[0]; ly = p[1]; points++;
    $('#sign-msg').textContent = '';
  });
  ['pointerup', 'pointercancel'].forEach(function (t) { pad.addEventListener(t, function () { drawing = false; }); });

  function openSign() {
    dlg.hidden = false;
    document.body.classList.add('lock');
    sizePad();
    $('#sign-msg').textContent = '';
    $('#sign-go').focus({ preventScroll: true });
  }
  function closeSign() {
    dlg.hidden = true;
    if (story.hidden) document.body.classList.remove('lock');
    openBtn.focus({ preventScroll: true });
  }

  function clearTimers() { timers.forEach(clearTimeout); timers = []; }
  function later(fn, ms) { timers.push(setTimeout(fn, ms)); }

  function bubbleEl(item) {
    var b = document.createElement('div');
    b.className = 'sb' + (item[2] ? ' big' : '');
    var t = document.createElement('b'); t.textContent = item[0];
    var p = document.createElement('p'); p.textContent = item[1];
    b.appendChild(t); b.appendChild(p);
    for (var i = 0; i < 3; i++) {
      var s = document.createElement('span');
      s.className = 'tw'; s.textContent = '✦';
      s.style.left = (Math.random() * 110 - 5) + '%';
      s.style.top = (Math.random() * 110 - 15) + '%';
      s.style.animationDelay = (Math.random() * 2) + 's';
      b.appendChild(s);
    }
    return b;
  }

  // Bố cục: màn rộng -> vòng tròn bong bóng quanh bông hoa (như video);
  // màn hẹp -> lưới 3 cột, hàng cuối căn giữa.
  function layout() {
    var W = innerWidth, H = innerHeight, n = ITEMS.length, out = [];
    var ring = W >= 900 && H >= 560;
    story.classList.toggle('ring', ring);
    if (ring) {
      var m = 14, size = Math.min(190, (Math.min(W, H) - 60) / 4.2), rx, ry, pts, L;
      for (var it = 0; it < 3; it++) {
        rx = (W - size) / 2 - m; ry = (H - size) / 2 - m - 6;
        pts = [[0, -ry, 0]]; L = 0;
        for (var q = 1; q <= 480; q++) {
          var t = -Math.PI / 2 + q * 2 * Math.PI / 480, x = rx * Math.cos(t), y = ry * Math.sin(t), pr = pts[pts.length - 1];
          L += Math.hypot(x - pr[0], y - pr[1]); pts.push([x, y, L]);
        }
        size = Math.min(size, L / n * 0.9);
      }
      story.style.setProperty('--scene', Math.max(160, 2 * (ry - size / 2 - 12)) + 'px');
      for (var i = 0, k2 = 0; i < n; i++) {
        var target = i * L / n;
        while (k2 < pts.length - 1 && pts[k2][2] < target) k2++;
        out.push({ size: size, fs: size * 1.12, x: W / 2 + pts[k2][0] - size / 2, y: H / 2 + pts[k2][1] - size / 2 });
      }
      return out;
    }
    story.style.removeProperty('--scene');
    var cols = W < 640 ? 3 : 4, rows = Math.ceil(n / cols);
    var cw = W / cols, ch = (H - 70) / rows, s = Math.min(cw, ch) * 0.96;
    for (var k = 0; k < n; k++) {
      var r = Math.floor(k / cols), c = k % cols, inRow = Math.min(cols, n - r * cols);
      out.push({ size: s, fs: s * 1.1, x: (cols - inRow) * cw / 2 + c * cw + (cw - s) / 2, y: 60 + r * ch + (ch - s) / 2 });
    }
    return out;
  }

  function sky() {
    var el = $('#st-sky'), out = '';
    for (var i = 0; i < 46; i++) out += '<i style="left:' + (Math.random() * 100) + '%;top:' + (Math.random() * 100) + '%;animation-delay:' + (Math.random() * 3).toFixed(2) + 's;--z:' + (1 + Math.random() * 1.6).toFixed(1) + 'px"></i>';
    for (i = 0; i < 14; i++) out += '<u style="left:' + (Math.random() * 100) + '%;animation-delay:' + (Math.random() * 9).toFixed(2) + 's;animation-duration:' + (8 + Math.random() * 7).toFixed(1) + 's"></u>';
    out += '<s style="top:12%;left:70%"></s><s class="s2" style="top:30%;left:95%"></s>';
    el.innerHTML = out;
  }

  // Hiện từng cái một, hiện đủ rồi tất cả cùng tan, nghỉ, rồi chạy lại từ đầu.
  function run() {
    var field = $('#st-field'), pos = layout(), els = [], i = 0;
    (function tick() {
      var b = bubbleEl(ITEMS[i]), p = pos[i];
      b.style.cssText = 'width:' + p.size + 'px;height:' + p.size + 'px;left:' + p.x + 'px;top:' + p.y + 'px;--fs:' + p.fs + 'px;--d:' + ((i % 5) * 0.5) + 's';
      field.appendChild(b); els.push(b); i++;
      if (i < ITEMS.length) later(tick, GAP);
      else {
        later(function () { els.forEach(function (e) { e.classList.add('out'); }); }, HOLD);
        // tan hết rồi hiện lại tất cả cùng lúc, nằm yên (không lặp lại)
        later(function () {
          field.innerHTML = '';
          later(function () {
            ITEMS.forEach(function (it, k) {
              var b = bubbleEl(it), q = pos[k];
              b.classList.add('settled');
              b.style.cssText = 'width:' + q.size + 'px;height:' + q.size + 'px;left:' + q.x + 'px;top:' + q.y + 'px;--fs:' + q.fs + 'px';
              field.appendChild(b);
            });
          }, 700);
        }, HOLD + 1400);
      }
    })();
  }

  function reduced() { return !fxOn; }   // theo nút "Hiệu ứng" của trang, không theo cài đặt hệ điều hành

  function play() {
    var field = $('#st-field');
    field.innerHTML = '';
    clearTimers();
    sky();
    dlg.hidden = true;
    story.hidden = false;
    story.scrollTop = 0;
    document.body.classList.add('lock');
    $('#st-close').focus({ preventScroll: true });
    if (reduced()) {                      // tắt hiệu ứng: xếp tĩnh, không lặp
      // tắt hiệu ứng: dùng đúng bố cục như lúc bật, hiện đủ ngay và đứng yên
      var all = layout();
      ITEMS.forEach(function (it, k) {
        var b = bubbleEl(it), q = all[k];
        b.classList.add('settled');
        b.style.cssText = 'width:' + q.size + 'px;height:' + q.size + 'px;left:' + q.x + 'px;top:' + q.y + 'px;--fs:' + q.fs + 'px';
        field.appendChild(b);
      });
    } else {
      later(run, 900);
    }
  }

  function closeStory() {
    clearTimers();
    story.hidden = true;
    $('#st-field').innerHTML = '';
    document.body.classList.remove('lock');
    openBtn.focus({ preventScroll: true });
  }

  $('#st-close').addEventListener('click', closeStory);
  openBtn.addEventListener('click', openSign);
  $('#sign-cancel').addEventListener('click', closeSign);
  $('#sign-clear').addEventListener('click', sizePad);
  $('#sign-go').addEventListener('click', function () {
    if (points < 6) { $('#sign-msg').textContent = 'Hãy ký tên vào khung trước nhé.'; return; }
    play();                               // chữ ký chỉ dùng để xác nhận, không hiện lại
  });
  addEventListener('keydown', function (e) {
    if (e.key !== 'Escape') return;
    if (!story.hidden) closeStory(); else if (!dlg.hidden) closeSign();
  });
})();
